fn is_prime(n: i8) -> bool {
    // By definition, primes are >= 2.
    if n < 2 {
        return false;
    }

    // Trial division by all k with 2 <= k < n.
    // Note: n is i8, so this loop is tiny; convert to i16 to avoid any overflow concerns.
    let nn = n as i16;
    let mut k: i16 = 2;

    while k < nn {
        if nn % k == 0 {
            return false;
        }
        k += 1;
    }

    true
}